package org.monzobot.app;
import org.json.*;
import java.io.IOException;
import java.util.*;

/** Fake transports only: no real provider keys, HTTP requests or paid calls. */
public final class AiProvidersChecks {
 static int checks;
 static final String KEY="synthetic-secret-key-not-real";
 static void ok(boolean v){checks++;if(!v)throw new AssertionError("Provider check "+checks);}
 static JSONObject call(String id,String name)throws Exception{return new JSONObject().put("id",id).put("type","function").put("function",new JSONObject().put("name",name).put("arguments","{}"));}
 static JSONObject canonical()throws Exception{return new JSONObject().put("model","synthetic-tool-model").put("max_completion_tokens",800).put("store",false).put("response_format",new JSONObject().put("type","json_object")).put("tools",new JSONArray().put(new JSONObject().put("type","function").put("function",new JSONObject().put("name","read_only").put("description","Read-only local test").put("strict",true).put("parameters",new JSONObject().put("type","object").put("properties",new JSONObject()).put("additionalProperties",false).put("required",new JSONArray()))))).put("messages",new JSONArray().put(new JSONObject().put("role","system").put("content","Use local tools; final answer JSON.")).put(new JSONObject().put("role","user").put("content","Synthetic question"))).put("tool_choice","required");}
 static JSONObject openAi(String text)throws Exception{return new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("finish_reason","stop").put("message",new JSONObject().put("role","assistant").put("content",text))));}
 static JSONObject anthropic(String text)throws Exception{return new JSONObject().put("type","message").put("role","assistant").put("stop_reason","end_turn").put("content",new JSONArray().put(new JSONObject().put("type","text").put("text",text)));}
 interface Attempt{void run()throws Exception;}
 static void rejected(Attempt a)throws Exception{checks++;try{a.run();throw new AssertionError("Expected provider rejection "+checks);}catch(IOException|IllegalArgumentException|JSONException expected){ok(!String.valueOf(expected.getMessage()).contains(KEY));}}
 static class Fake implements AiProviders.Transport{
  int count;String endpoint;Map<String,String> headers;JSONObject body,response;
  Fake(JSONObject response){this.response=response;}
  public JSONObject post(String e,Map<String,String> h,JSONObject b)throws Exception{count++;endpoint=e;headers=h;body=new JSONObject(b.toString());return response;}
 }
 public static void main(String[] args)throws Exception{
  checks=0;ok(AiProviders.fromId("openai")==AiProviders.Provider.OPENAI);ok(AiProviders.fromId("anthropic")==AiProviders.Provider.ANTHROPIC);rejected(()->AiProviders.fromId("custom-endpoint"));
  ok(AiProviders.Provider.OPENAI.defaultModel.equals("gpt-4.1-mini"));ok(AiProviders.Provider.ANTHROPIC.defaultModel.equals("claude-haiku-4-5-20251001"));ok(AiProviders.Provider.OPENAI.modelNote.contains("Legacy"));ok(AiProviders.Provider.ANTHROPIC.host.equals("api.anthropic.com"));
  JSONObject original=canonical();String before=original.toString();Fake open=new Fake(openAi("{\"interpretation\":\"test\"}"));JSONObject openAnswer=AiProviders.gateway(AiProviders.Provider.OPENAI,open).complete(original,KEY);
  ok(open.count==1);ok(open.endpoint.equals("https://api.openai.com/v1/chat/completions"));ok(open.headers.get("Authorization").equals("Bearer "+KEY));ok(!open.headers.containsKey("x-api-key"));ok(!open.headers.containsKey("anthropic-version"));ok(open.body.getBoolean("store")==false);ok(open.body.getJSONObject("response_format").getString("type").equals("json_object"));ok(!open.body.toString().contains(KEY));ok(original.toString().equals(before));ok(openAnswer.getJSONArray("choices").length()==1);
  Fake nativeAnthropic=new Fake(anthropic("{\"interpretation\":\"test\"}"));JSONObject answer=AiProviders.gateway(AiProviders.Provider.ANTHROPIC,nativeAnthropic).complete(canonical(),KEY);
  ok(nativeAnthropic.count==1);ok(nativeAnthropic.endpoint.equals("https://api.anthropic.com/v1/messages"));ok(nativeAnthropic.headers.get("x-api-key").equals(KEY));ok(nativeAnthropic.headers.get("anthropic-version").equals("2026-10-21"));ok(!nativeAnthropic.headers.containsKey("Authorization"));ok(!nativeAnthropic.body.toString().contains(KEY));
  JSONObject body=nativeAnthropic.body;ok(body.getInt("max_tokens")==800);ok(body.getString("system").contains("final answer JSON"));ok(body.getJSONObject("tool_choice").getString("type").equals("any"));ok(!body.has("store"));ok(!body.has("response_format"));ok(!body.has("max_completion_tokens"));ok(body.getJSONArray("tools").getJSONObject(0).has("input_schema"));ok(!body.getJSONArray("tools").getJSONObject(0).has("function"));ok(answer.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content").contains("interpretation"));
  JSONObject multi=canonical();JSONArray messages=multi.getJSONArray("messages");messages.put(new JSONObject().put("role","assistant").put("content",JSONObject.NULL).put("tool_calls",new JSONArray().put(call("call_A","read_only")).put(call("call_B","read_only"))));messages.put(new JSONObject().put("role","tool").put("tool_call_id","call_A").put("content","{\"value\":10}"));messages.put(new JSONObject().put("role","tool").put("tool_call_id","call_B").put("content","{\"error\":\"invalid local arguments\"}"));
  Fake multiple=new Fake(anthropic("{}"));AiProviders.gateway(AiProviders.Provider.ANTHROPIC,multiple).complete(multi,KEY);JSONArray converted=multiple.body.getJSONArray("messages");ok(converted.length()==3);ok(converted.getJSONObject(1).getJSONArray("content").length()==2);ok(converted.getJSONObject(1).getJSONArray("content").getJSONObject(0).getString("type").equals("tool_use"));ok(converted.getJSONObject(1).getJSONArray("content").getJSONObject(0).getJSONObject("input").length()==0);JSONArray results=converted.getJSONObject(2).getJSONArray("content");ok(results.length()==2);ok(results.getJSONObject(0).getString("tool_use_id").equals("call_A"));ok(results.getJSONObject(1).getBoolean("is_error"));
  JSONObject nativeCalls=anthropic("read");nativeCalls.put("stop_reason","tool_use").getJSONArray("content").put(new JSONObject().put("type","tool_use").put("id","tool_A").put("name","read_only").put("input",new JSONObject().put("limit",1))).put(new JSONObject().put("type","tool_use").put("id","tool_B").put("name","read_only").put("input",new JSONObject()));
  JSONObject normalized=AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(nativeCalls)).complete(canonical(),KEY);JSONArray calls=normalized.getJSONArray("choices").getJSONObject(0).getJSONObject("message").getJSONArray("tool_calls");ok(calls.length()==2);ok(calls.getJSONObject(0).getString("id").equals("tool_A"));ok(new JSONObject(calls.getJSONObject(0).getJSONObject("function").getString("arguments")).getInt("limit")==1);
  for(String choice:new String[]{"auto","none"}){JSONObject req=canonical().put("tool_choice",choice);Fake f=new Fake(anthropic("{}"));AiProviders.gateway(AiProviders.Provider.ANTHROPIC,f).complete(req,KEY);ok(f.body.getJSONObject("tool_choice").getString("type").equals(choice));}
  for(String role:new String[]{"developer","function","cloud_service"}){JSONObject req=canonical();req.getJSONArray("messages").put(new JSONObject().put("role",role).put("content","bad"));Fake f=new Fake(anthropic("{}"));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,f).complete(req,KEY));ok(f.count==0);}
  JSONObject orphan=canonical();orphan.getJSONArray("messages").put(new JSONObject().put("role","tool").put("tool_call_id","not_pending").put("content","{}"));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(anthropic("{}"))).complete(orphan,KEY));
  JSONObject missing=canonical();missing.getJSONArray("messages").put(new JSONObject().put("role","assistant").put("tool_calls",new JSONArray().put(call("pending","read_only"))));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(anthropic("{}"))).complete(missing,KEY));
  for(String key:new String[]{"",KEY+"\nInjected: bad",KEY+" value"}){Fake f=new Fake(openAi("{}"));rejected(()->AiProviders.gateway(AiProviders.Provider.OPENAI,f).complete(canonical(),key));ok(f.count==0);}
  for(String field:new String[]{"endpoint","headers","stream","temperature","metadata"}){JSONObject req=canonical().put(field,"unsupported");Fake f=new Fake(anthropic("{}"));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,f).complete(req,KEY));ok(f.count==0);}
  JSONObject huge=canonical();huge.getJSONArray("messages").getJSONObject(1).put("content",new String(new char[AiProviders.MAX_BODY_BYTES]).replace('\0','x'));Fake never=new Fake(anthropic("{}"));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,never).complete(huge,KEY));ok(never.count==0);
  Fake tooLarge=new Fake(anthropic(new String(new char[AiProviders.MAX_RESPONSE_BYTES]).replace('\0','x')));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,tooLarge).complete(canonical(),KEY));ok(tooLarge.count==1);
  for(String reason:new String[]{"refusal","max_tokens","pause_turn"}){JSONObject resp=anthropic("untrusted").put("stop_reason",reason);rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(resp)).complete(canonical(),KEY));}
  JSONObject refusal=openAi("{}");refusal.getJSONArray("choices").getJSONObject(0).getJSONObject("message").put("refusal","Cannot comply");rejected(()->AiProviders.gateway(AiProviders.Provider.OPENAI,new Fake(refusal)).complete(canonical(),KEY));
  JSONObject malformed=anthropic("{}");malformed.getJSONArray("content").put(new JSONObject().put("type","server_tool_use").put("id","cloud"));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(malformed)).complete(canonical(),KEY));
  JSONObject badInput=anthropic("{}").put("stop_reason","tool_use");badInput.getJSONArray("content").put(new JSONObject().put("type","tool_use").put("id","call").put("name","read_only").put("input",new JSONArray()));rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,new Fake(badInput)).complete(canonical(),KEY));
  Fake once=new Fake(anthropic("{}")){@Override public JSONObject post(String endpoint,Map<String,String> headers,JSONObject request)throws Exception{count++;throw new IOException("Synthetic transport failure");}};rejected(()->AiProviders.gateway(AiProviders.Provider.ANTHROPIC,once).complete(canonical(),KEY));ok(once.count==1);
  System.out.println(checks+" AI provider checks passed; fake transports only, no network or real keys.");
 }
}
